import glob,re,collections
rows={}
for f in glob.glob('.archon-horizon/roadmap/items/*.yaml'):
    t=open(f).read()
    i=re.search(r'^id:\s*(\S+)',t,re.M).group(1)
    st=re.search(r'^status:\s*(\S+)',t,re.M).group(1)
    pa=re.search(r'^\s*parent:\s*(\S+)',t,re.M)
    rows[i]=(st,pa.group(1) if pa else None)
kids=collections.defaultdict(list)
for i,(s,p) in rows.items():
    if p: kids[p].append(i)
OPEN={'active','pending','blocked'}
for i,(s,p) in sorted(rows.items()):
    if not i.startswith('AJCR.w4-rep'): continue
    ks=kids.get(i,[])
    if not ks: continue
    st=[rows[k][0] for k in ks]
    if s in OPEN and all(x in ('done','rejected') for x in st): print('ALL-CHILDREN-DONE parent open:',i,s,st)
    if s=='done' and any(x in OPEN for x in st): print('DONE parent, open child:',i,[ (k,rows[k][0]) for k in ks if rows[k][0] in OPEN])
print('--- certificate row ---')
print(open('.archon-horizon/roadmap/items/AJCR.w4-rep.datum.dat-d.ddr.certificate.yaml').read()[:1800])
"

