import re,os,glob
root='MainProjects/Algebraic-Jacobian-Challenge-Rebuild'
imps=set(re.findall(r'import (AlgebraicJacobian\S*)',open(root+'/AlgebraicJacobian.lean').read()))
seen=set()
def walk(m):
    if m in seen: return
    seen.add(m)
    p=root+'/'+m.replace('.','/')+'.lean'
    if os.path.exists(p):
        for x in re.findall(r'import (AlgebraicJacobian\S*)',open(p).read()): walk(x)
for m in imps: walk(m)
allf=[f for f in glob.glob(root+'/AlgebraicJacobian/**/*.lean',recursive=True)]
def mod(f): return f[len(root)+1:-5].replace('/','.')
un=[f for f in allf if mod(f) not in seen]
print('total',len(allf),'reachable',len([f for f in allf if mod(f) in seen]),'unrooted',len(un))
for f in un: print('  ',f)
"
